import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';

export default function VolunteerDonorSection({ me, events, token, setMsg, activities }) {
  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);

  useEffect(()=>{
    if (!token) return;
    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/achievements',{headers:{Authorization:`Bearer ${token}`}})
      .then(r=>r.json()).then(d=>{ setAchievements(d); }).catch(e=>{});
  },[token]);

  async function loadMyNgos(){
    if (!token) { setMsg('Please login'); return; }
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/my-ngos',{headers:{Authorization:`Bearer ${token}`}});
    const d = await res.json(); setMyNgos(d.ngos || []);
  }

  async function viewNgoDetails(id){
    if (!token) { setMsg('Please login'); return; }
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngo/' + id,{headers:{Authorization:`Bearer ${token}`}});
    const d = await res.json(); setSelectedNgo(d);
  }

  return (
    <div className="panel" style={{display:'flex',gap:16}}>
      {/* Left: achievements / badges */}
      <div style={{width:280,flexShrink:0}}>
        <h4>Achievements</h4>
        <div style={{marginBottom:12}}>
          <div className="stat-card"><div className="stat-num">{me.points||0}</div><div className="stat-label">Points</div></div>
        </div>

        <div style={{marginTop:10}}>
          <h5>Badges</h5>
          {achievements ? (achievements.badges.length ? achievements.badges.map(b=> (
            <div key={b.key} style={{padding:8,background:'#fff',borderRadius:8,marginBottom:8}}>
              <strong>{b.title}</strong>
              <div style={{fontSize:13,color:'#666'}}>{b.desc}</div>
            </div>
          )) : <p>No badges yet.</p>) : <p>Loading...</p>}
        </div>

        <div style={{marginTop:12}}>
          <button onClick={loadMyNgos}>My NGOs</button>
          <div style={{marginTop:8}}>
            {myNgos.map(n=> (
              <div key={n.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:8,background:'#fff',borderRadius:8,marginTop:8}}>
                <div><strong>{n.name}</strong><div style={{fontSize:12,color:'#666'}}>{n.email}</div></div>
                <button onClick={()=>viewNgoDetails(n.id)}>View</button>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Middle: main actions*/}
      <div style={{flex:1}}>
        <h3>Recognition & Actions</h3>
        <p><strong>Name:</strong> {me.name} — <strong>Level:</strong> {me.points >= 200 ? 'Gold' : me.points >= 100 ? 'Silver' : me.points >= 50 ? 'Bronze' : me.points >= 10 ? 'Member' : 'New'}</p>

        <div style={{background:'#fff',padding:12,borderRadius:8,boxShadow:'0 8px 24px rgba(2,6,23,0.04)'}}>
          <h4>Give Feedback</h4>
          <Feedback token={token} setMsg={setMsg} />

          <h4 style={{marginTop:12}}>Donate</h4>
          <Donate token={token} setMsg={setMsg} />

          <h4 style={{marginTop:12}}>Volunteer for Event</h4>
          <Volunteer token={token} events={events} setMsg={setMsg} />
        </div>
      </div>

      {/* Right: details box */}
      <div style={{width:340,flexShrink:0}}>
        <h4>Details</h4>
        {selectedNgo ? (
          <div style={{background:'#fff',padding:12,borderRadius:10}}>
            <h5>{selectedNgo.ngo.name}</h5>
            <div style={{fontSize:13,color:'#666'}}>{selectedNgo.ngo.email}</div>
            <div style={{marginTop:10}}>
              <strong>Events</strong>
              {selectedNgo.events.length ? selectedNgo.events.map(ev=> (
                <div key={ev.id} style={{padding:8,borderBottom:'1px solid #f0f0f0'}}>{ev.title}</div>
              )) : <div>No events yet.</div>}
            </div>
            <div style={{marginTop:10}}>
              <strong>Recent Donations</strong>
              {selectedNgo.donations.length ? selectedNgo.donations.slice(0,6).map(d=> (<div key={d.id} style={{padding:6}}>{d.donor_name} — ₹{d.amount}</div>)) : <div>No donations yet.</div>}
            </div>
          </div>
        ) : (
          <div style={{background:'#fff',padding:12,borderRadius:10}}>Select an NGO to see details.</div>
        )}
      </div>
    </div>
  );
}
